Full C code:
```
#include <stdio.h>
#include <stdlib.h>
#define BASE 1000000000
typedef struct { int len; int *d; } Bi;
static Bi *new_num(void) {
  Bi *b = (Bi *)calloc(1, sizeof(Bi));
  b->d = (int *)calloc(1, sizeof(int));
  b->len = 1;
  return b;
}
static void set_small(Bi *b, int v) {
  free(b->d);
  b->d = (int *)calloc(1, sizeof(int));
  b->len = 1;
  b->d[0] = v;
}
static Bi *add_num(Bi *a, Bi *b) {
  int n = a->len > b->len ? a->len : b->len;
  Bi *c = new_num();
  c->d = (int *)calloc((size_t)n + 1, sizeof(int));
  int carry = 0;
  for (int i = 0; i < n; i++) {
    long long s = carry;
    if (i < a->len) s += a->d[i];
    if (i < b->len) s += b->d[i];
    c->d[i] = (int)(s % BASE);
    carry = (int)(s / BASE);
  }
  if (carry) {
    c->d[n] = carry;
    c->len = n + 1;
  } else {
    c->len = n;
  }
  while (c->len > 1 && c->d[c->len - 1] == 0) c->len--;
  return c;
}
static void print_num(Bi *b) {
  printf("%d", b->d[b->len - 1]);
  for (int i = b->len - 2; i >= 0; i--) {
    printf("%09d", b->d[i]);
  }
  puts("");
}
int main(int argc, char **argv) {
  long long n = 0;
  if (argc > 1) n = atoll(argv[1]);
  if (n < 0) n = 0;
  Bi *a = new_num();
  Bi *b = new_num();
  set_small(b, 1);
  for (long long i = 0; i < n; i++) {
    Bi *c = add_num(a, b);
    free(a->d);
    free(a);
    a = b;
    b = c;
  }
  print_num(a);
  free(a->d);
  free(a);
  free(b->d);
  free(b);
  return 0;
}
```
